/**
 * Fachada de ACCESOBD04 (S500L040). Cada entry point del EXPORT es un método con la misma
 * convención de retorno: 0 = OK, 1 = NOTFOUND, 2 = error de base, 3 = área de entrada corta.
 * Los clientes siguen entrando por un adaptador equivalente a S500L040LIGA.
 */
public interface AccesoBd04Service {

    ResultadoL040<FechaS111>       fechaS111();                         // S500L040_FECHA_S111_C
    ResultadoL040<RelacionTarjeta> dameTarjeta(String contrato12);      // S500L040_DAME_TARJETA_C
    ResultadoL040<RelacionTarjeta> dameContrato(String tarjeta16);      // S500L040_DAME_CONTRATO_C
    ResultadoL040<DatosTef>        dameTef(String tarjeta16);           // S500L040_DAME_TEF_C
    ResultadoL040<CuentaOrigen>    dameCtaOrig(LlaveCuentaGlobal llave);  // S500L040_DAME_CTAORIG_C
    ResultadoL040<CuentaGlobal>    dameCtaGlb(LlaveCuentaOrigen llave);   // S500L040_DAME_CTAGLB_C
    ResultadoL040<UltimoMovimiento> conInfoCte(String cliente12);       // S500L040_CONINFOCTE_C
    int cambiaModoBase(ModoBase modo);                                  // S500L040_CAMBASE_C
    RespuestaDispersion archDisp(AreaComunDispersion area);            // S500L040_ARCHDISP_C
    // S500L040_99_LEVANTA_C no se traduce: era un no-op para forzar el enlace de la librería.
}

public record ResultadoL040<T>(int codigo, Optional<T> datos) {
    public static final int OK = 0, NOTFOUND = 1, ERROR_BASE = 2, ENTRADA_CORTA = 3;
}

// FREEZE(TEMPORARY): la librería queda residente mientras tenga clientes enlazados.
// En Spring es un bean singleton; PROC_INICIO y PROC_FIN pasan a @PostConstruct y @PreDestroy.
@Service
@RequiredArgsConstructor
class AccesoBd04ServiceImpl implements AccesoBd04Service {
    private final ModoBaseManager modoBase;
    private final MotorDispersion motor;

    @PostConstruct void procInicio() { modoBase.abreSegunTipoProceso(); }        // PROC_INICIO
    @PreDestroy    void procFin()    { motor.terminaProcesosHijo(); motor.terminaDispersionEnCurso(); }  // PROC_FIN
    // ...
}

/** AREACOMUN de S500L040_ARCHDISP_C (155 bytes EBCDIC). */
public record AreaComunDispersion(
        FuncionDispersion funcion,     // [0]  9(001)  1..4
        long numRegistro,              // [1]  9(008)
        int numCopia,                  // [9]  9(002)  1..7
        int mix,                       // [11] 9(006)
        LocalDate fechaLinea,          // [17] 9(008)  AAAAMMDD
        String mensaje) {              // [25] X(130)

    /** Desglose del mensaje para la función 3 (escribe resultado de dispersión). */
    public ResultadoMovimiento comoResultado() {
        var m = mensaje;
        return new ResultadoMovimiento(
                Fixed.entero(m, 0, 1), Fixed.entero(m, 1, 8),    // tipo_reg, num_sec
                Fixed.entero(m, 9, 4), Fixed.entero(m, 13, 2),   // sucursal, caja
                Fixed.entero(m, 15, 8), Fixed.entero(m, 23, 4),  // num_tran, cve_tran
                Fixed.entero(m, 27, 1), Fixed.entero(m, 28, 2),  // tipo_mov, medio de acceso
                m.substring(30, 46),                             // tarjeta 9(16) como String
                Fixed.decimal(m, 46, 16, 2),                     // importe 9(14)V99 -> escala 2
                Fixed.entero(m, 62, 3),                          // moneda
                m.substring(65, 77),                             // referencia 9(12) como String
                EstadoMovimiento.of(Fixed.entero(m, 77, 1)),     // 1 aplicado, 2 rechazado, 3 foráneo
                Fixed.entero(m, 78, 4), m.substring(82, 130).strip());
    }
}

public enum FuncionDispersion { HAY_ARCHIVO, LEE, ESCRIBE, CREA_X_HORARIO }

public sealed interface RespuestaDispersion {
    record Existe(boolean hayArchivo) implements RespuestaDispersion {}                  // F1: 1 sí, 2 no
    record Lectura(boolean fin, long numReg, String registro880) implements RespuestaDispersion {}  // F2
    record Escritura(boolean error, long numReg) implements RespuestaDispersion {}       // F3: 1 error, 2 OK
}

