// de log del paquete, administrable por Actuator (/actuator/loggers) con control de acceso.

@Component
@RequiredArgsConstructor
class ModoBaseManager {
    private final RetryTemplate reintentoApertura;   // backoff exponencial y tope de intentos
    private volatile ModoBase modoActual;            // IG_BD_OPEN_MODE: 0 cerrada, 1 INQUIRY, 2 UPDATE
    private boolean estabaDeInquiry;                 // BG_BD_ESTABA_DE_INQUIRY

    /** FORZA_BASE_EN_UPDATE: lo usan la función 4 del motor y PROC_FIN. */
    synchronized void forzaUpdate() {
        estabaDeInquiry = false;
        if (modoActual == ModoBase.INQUIRY) {
            estabaDeInquiry = true;
            reintentoApertura.execute(ctx -> {
                cambiaA(ModoBase.UPDATE);            // CIERRA_BASE + ABRE_BASE en UPDATE
                if (modoActual != ModoBase.UPDATE) throw new BaseNoDisponibleException(ctx.getRetryCount());
                return null;
            });
        }
    }

    /** REGRESA_BASE_A_INQUIRY: deshace el forzado si la base estaba en consulta. */
    synchronized void regresaAInquiry() {
        if (estabaDeInquiry) reintentoApertura.execute(ctx -> { cambiaA(ModoBase.INQUIRY); return null; });
    }
}

@Service
@RequiredArgsConstructor
class MotorDispersion {
    private final ReentrantLock lkDisparch = new ReentrantLock();   // INTERLOCK LK_DISPARCH
    private final CalendarioBancario calendario;                     // LOCSUP.THECALENDAR fn 20

    /** S500L040_ARCHDISP_C. Códigos: 1 función inválida, 2 fecha inválida, 9 copia inválida. */
    public RespuestaDispersion archDisp(int funcion, AreaComunDispersion area) {
        lkDisparch.lock();
        try {
            if (funcion < 1 || funcion > 4) return RespuestaDispersion.error(1);
            if (!calendario.esFechaValida(area.fechaLinea())) return RespuestaDispersion.error(2);
            if (funcion < 4 && (area.numCopia() < 1 || area.numCopia() > 7)) {
                return RespuestaDispersion.error(9);
            }
            return switch (funcion) {
                case 1 -> hayArchivoADispersar(area);     // HAY_ARCHIVO_A_DISPER
                case 2 -> leeArchivoADispersar(area);     // LEE_ARCHIVO_A_DISPER
                case 3 -> escribeEnArchivoDisper(area);   // ESCRIBE_EN_ARCHIVO_DISPER
                default -> creaDisperXHorario(area);      // CREA_DISPER_X_HORARIO
            };
        } finally {
            lkDisparch.unlock();                          // también cubre la EXCEPTION PROCEDURE LIBERA
        }
    }
}

@Component
@RequiredArgsConstructor
class ControlArriboTx {
    private final TransactionTemplate tx;            // PROPAGATION_REQUIRES_NEW, aislamiento READ_COMMITTED

    /**
     * BEGIN_TRANSAC_DB / ENDTRANSACTION AUDIT. En DMSII el resultado 2 (ABORT) hacía esperar
     * WAIT((5)) y el llamador reintentaba; aquí el reintento es declarativo y acotado.
     */
    @Retryable(retryFor = {CannotAcquireLockException.class, DeadlockLoserDataAccessException.class},
               maxAttempts = 5, backoff = @Backoff(delay = 5000))
    public <T> T enTransaccion(Supplier<T> trabajo) {
        return tx.execute(status -> trabajo.get());   // commit al salir = ENDTRANSACTION
    }
}
